list.query:
SELECT DISTINCT category AS __text, category AS __value FROM (
    SELECT category FROM public.city_category_minute_statistics
    WHERE stat_minute_utc >= ($__timeFrom()::timestamptz) AND stat_minute_utc < ($__timeTo()::timestamptz)
      AND definition_version = 'observed-city-category-statistics-v1' AND city_slug = ${city:sqlstring}
    UNION
    SELECT category FROM public.city_category_hour_statistics
    WHERE hour_start_utc < ($__timeTo()::timestamptz) AND hour_start_utc + interval '1 hour' > ($__timeFrom()::timestamptz)
      AND definition_version = 'observed-city-category-statistics-v1' AND city_slug = ${city:sqlstring}
) retained ORDER BY __text LIMIT 100;
